-- GenDB engine variant Q12-conjunct_permutation: template q12.sql, kind conjunct_permutation (generated by generate.py; frozen)
SELECT
  l_shipmode,
  SUM(
    CASE
      WHEN o_orderpriority = '1-URGENT' OR o_orderpriority = '2-HIGH'
      THEN 1
      ELSE 0
    END
  ) AS high_line_count,
  SUM(
    CASE
      WHEN o_orderpriority <> '1-URGENT' AND o_orderpriority <> '2-HIGH'
      THEN 1
      ELSE 0
    END
  ) AS low_line_count
FROM orders, lineitem
WHERE
  l_receiptdate < $3 + INTERVAL '1 YEAR'
  AND l_receiptdate >= $3
  AND l_shipdate < l_commitdate
  AND l_commitdate < l_receiptdate
  AND l_shipmode IN ($1, $2)
  AND o_orderkey = l_orderkey
GROUP BY
  l_shipmode
ORDER BY
  l_shipmode
